async function openPhoto(pid){const p=photos.get(pid);if(!isPhotoRecord(p))return;const hit=await findOriginalFile(p,true);if(!hit){toast('الأصل غير مرتبط حاليًا؛ أبقيت المعاينة الصغيرة فقط ولم أفتح صورة مبكسلة.');return}const m=state.memories.find(x=>x.photoIds?.includes(pid));lb.ids=m?photoFor(m).map(x=>x.id):[pid];lb.i=Math.max(0,lb.ids.indexOf(pid));lb.slideIds=null;stopSlideshow();resetLbZoom();romanticHeartTransition('open');$('#lightbox').showModal();await showPhoto(false,URL.createObjectURL(hit.file))}
function cleanupLbFlip(){const el=$('#lbFlip');if(el){el.classList.remove('play-next','play-prev');el.hidden=true}for(const u of lb.flipUrls.splice(0)){try{URL.revokeObjectURL(u)}catch{}}lb.flipBusy=false;if(lb.flipTimer){clearTimeout(lb.flipTimer);lb.flipTimer=null}}
