async function showPhoto(keepCurrent=false,preloadedUrl=null){const p=photos.get(lb.ids[lb.i]);if(!isPhotoRecord(p))return;const img=$('#lbImage');const token=++lb.loadToken;resetLbZoom();const oldUrl=lb.url;if(lb.thumbUrl){try{URL.revokeObjectURL(lb.thumbUrl)}catch{}lb.thumbUrl=null}updateLbMeta();$('#lbStatus').textContent='جارٍ تحميل الصورة الأصلية…';try{const u=preloadedUrl||await getOriginalUrlForPhoto(p);if(token!==lb.loadToken){try{URL.revokeObjectURL(u)}catch{}return}if(img){img.hidden=false;img.src=u}if(oldUrl&&oldUrl!==u){try{URL.revokeObjectURL(oldUrl)}catch{}}lb.url=u;$('#lbStatus').textContent='';}catch{if(token!==lb.loadToken)return;if(img){img.hidden=true;img.removeAttribute('src')}$('#lbStatus').textContent='الأصل غير متاح حاليًا؛ المعاينة الصغيرة فقط متاحة في الألبوم.'}}
