async function saveAlbumMove(from,ids){const title=$('#albumTitle2').value.trim();if(!title){toast('اكتب اسم الألبوم.');return}if(state.memories.some(m=>String(m.title||'').trim()===title)){toast('يوجد ألبوم بهذا الاسم بالفعل.');return}const t={id:id('mem'),title,date:'',endDate:'',place:'',description:'',album:title,photoIds:[]};state.memories.unshift(t);const m=state.memories.find(x=>x.id===from);for(const pid of ids){if(m)m.photoIds=m.photoIds.filter(x=>x!==pid);t.photoIds.push(pid);const p=photos.get(pid);if(p){p.manualAlbum=true;p.layoutLocked=true;p.album=title;await savePhoto(p)}}selectedPhotos.clear();await save();closeModal();toast(`تم إنشاء «${title}» ونقل الصور إليه.`);renderNoAnim()}
async function excludeSelected(){if(!requireSelection())return;const current=state.memories.find(x=>x.id===currentMemoryId);const ids=[...selectedPhotos];if(!current)return;if(!confirm('استبعاد الصور من فهرس OsRa؟ الصور الأصلية لن تُحذف من الجهاز.'))return;const refs=new Map();for(const pid of ids){refs.set(pid,state.memories.filter(m=>Array.isArray(m.photoIds)&&m.photoIds.includes(pid)).map(m=>({memoryId:m.id,index:m.photoIds.indexOf(pid)})))}for(const pid of ids){const p=photos.get(pid);if(!p)continue;state.excludedPhotos.push({id:p.id,key:exclusionKey(p.relPath,p.size,p.lastModified,p.fingerprint||''),relPath:p.relPath,sourceId:p.sourceId||'',sourceLinks:photoLocations(p),size:p.size,lastModified:p.lastModified,name:p.name,fingerprint:p.fingerprint||'',contentKey:p.contentKey||'',matchKey:p.matchKey||'',album:p.album||'',manualAlbum:!!p.manualAlbum,autoAlbum:p.autoAlbum!==false,layoutLocked:!!p.layoutLocked,addedAt:p.addedAt||Date.now(),capturedAt:p.capturedAt||'',memoryRefs:refs.get(pid)||[]});photos.delete(pid);await deletePhotoRecord(pid)}for(const mem of state.memories)mem.photoIds=(mem.photoIds||[]).filter(pid=>!selectedPhotos.has(pid));state.excludedPhotos=[...new Map(state.excludedPhotos.map(x=>[x.contentKey||x.fingerprint||x.key,x])).values()];selectedPhotos.clear();await save();toast('تم استبعاد الصور من فهرس OsRa دون حذف الأصل أو الاحتفاظ بنسخة المصغرة داخل الفهرس.');renderNoAnim()}
async function reorderPhoto(pid,dir){const m=state.memories.find(x=>x.id===currentMemoryId);if(!m)return;const arr=m.photoIds||[],p=photos.get(pid);if(!isPhotoRecord(p))return;const slots=arr.map((x,i)=>isPhotoRecord(photos.get(x))?i:-1).filter(i=>i>=0),at=slots.indexOf(arr.indexOf(pid)),to=at+dir;if(at<0||to<0||to>=slots.length)return;const next=[...arr],a=slots[at],b=slots[to];[next[a],next[b]]=[next[b],next[a]];m.photoIds=next;await save();renderNoAnim()}
async function restoreExcluded(){if(!state.excludedPhotos.length&&!reindexRestorePool.length){toast('لا توجد صور مستبعدة حاليًا لإعادة فهرستها.');return}if(scanLock){toast('أوقف الفحص الحالي قبل إعادة فهرسة الصور المستبعدة.');return}const pool=reindexRestorePool.length?[...reindexRestorePool]:structuredClone(state.excludedPhotos);reindexRestorePool=[...pool];await persistReindexPool();const sourceIds=new Set(pool.flatMap(x=>Array.isArray(x.sourceLinks)?x.sourceLinks.map(l=>l.sourceId):[x.sourceId]).filter(Boolean));toast('تم تجهيز إعادة الفهرسة الآمنة. الصور المستبعدة ستظل مستبعدة أمام الفحص العادي حتى تُعاد من هنا فقط.');await persistReindexPool();for(const sid of sourceIds){const s=sources.find(x=>x.id===sid);if(!s)continue;try{await setActiveSource(s);if(await ensureSourcePermission(s,true)){await clearScanProgress(s.id);await scan(s.handle,false,{source:s,fresh:true,reindex:true})}}catch(e){console.warn('reindex excluded source failed',e)}}await persistReindexPool();await save();toast(reindexRestorePool.length?`توقفت إعادة الفهرسة مع بقاء ${reindexRestorePool.length} صورة لم تُعثر على أصلها بعد؛ يمكنك المتابعة لاحقًا.`:(state.excludedPhotos.length?'اكتملت إعادة الفهرسة لما وُجد. الصور التي لم تُعثر عليها بقيت مستبعدة.':'اكتملت إعادة الفهرسة بنجاح.'));renderNoAnim()}
async function saveDream(i){let d=i?state.dreams.find(x=>x.id===i):null;if(!d){d={id:id('dream')};state.dreams.unshift(d)}d.title=$('#dTitle').value.trim()||'حلم';d.targetDate=$('#dDate').value;d.progress=Math.max(0,Math.min(100,Number($('#dProgress').value||0)));d.note=$('#dNote').value.trim();d.done=d.progress>=100;await save();closeModal();renderNoAnim()}
async function linkAllSources(){if(scanLock){toast('الفحص جارٍ بالفعل.');return}if(!sources.length){toast('أضف مجلدًا واحدًا على الأقل أولًا.');return}if(!confirm('سيبحث OsRa في كل المجلدات المرتبطة فقط عن الأصول الأصلية للصور المسجلة حاليًا، دون إضافة صور جديدة إلى الفهرس. سيعمل المجلدات واحدًا واحدًا لتقليل استهلاك الذاكرة على الهاتف، مع إلغاء كامل متاح في أي لحظة.'))return;scanCancelRequested=false;let done=0,skipped=0;for(const s of sources){if(scanCancelRequested)break;try{await setActiveSource(s);if(!(await ensureSourcePermission(s,true))){skipped++;continue}toast(`جارٍ البحث عن الأصول في «${sourceLabel(s)}»…`);await clearScanProgress(s.id);const result=await scan(s.handle,false,{source:s,fresh:true,matchOnly:true,batch:true});if(result?.cancelled||scanCancelRequested)break;done++}catch(e){console.warn('link all source failed',e);skipped++}}const cancelled=scanCancelRequested;scanCancelRequested=false;toast(cancelled?`تم إلغاء ربط الأصول بعد إكمال ${done} مجلدًا.`:`انتهى ربط الأصول: ${done} مجلد${skipped?' — تعذر الوصول إلى '+skipped+' مجلدات':''}.`);renderNoAnim()}
async function saveSettings(){for(const x of ['startDate','engagementDate','birthdayRania'])state.settings[x]=$('#set'+(x==='startDate'?'Start':x==='engagementDate'?'Eng':'Birth')).value;for(const [k,id2] of [['osamaPhone','setOsama'],['raniaPhone','setRania'],['whatsappUrl','setWA']])state.settings[k]=$('#'+id2).value.trim();normalizeState();await save();toast('تم حفظ الإعدادات.');renderNoAnim()}
